function conforms(value, schema) {
  if (Array.isArray(schema.anyOf)) {
    return schema.anyOf.some((option) => conforms(value, option));
  }
  if ('const' in schema) return value === schema.const;
  if (Array.isArray(schema.enum) && !schema.enum.includes(value)) return false;
  switch (schema.type) {
    case 'object': {
      if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return false;
      }
      const properties = schema.properties || {};
      return (
        Object.keys(value).every((key) => key in properties) &&
        (schema.required || []).every((key) => key in value) &&
        Object.entries(properties).every(
          ([key, property]) => !(key in value) || conforms(value[key], property),
        )
      );
    }
    case 'array':
      return (
        Array.isArray(value) &&
        value.every((item) => conforms(item, schema.items || {}))
      );
    case 'string':
      return typeof value === 'string';
    case 'number':
      return typeof value === 'number' && Number.isFinite(value);
    case 'integer':
      return Number.isInteger(value);
    case 'boolean':
      return typeof value === 'boolean';
    case 'null':
      return value === null;
    default:
      return true;
  }
}
